sys_script_include.script:
var FinCrimeSummarize = Class.create();
FinCrimeSummarize.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    summarizeQuote: function(recordSysID) {
        //gs.info("@@@asifa script include called");
        var table = 'x_vuram_financia_0_fcc_kyc_cases';
        recordSysID = this.getParameter('sysparm_recordSysId');
        //gs.info('@@@asifa' + recordSysID);
        var data;
        //   gs.info('I am in LLM For Quote - ' + recordSysID + ' - ' + (recordSysID && table));
        // if (recordSysID && table) {
        //     //gs.info('Inside first IF');
        //     data = new global.getTableAndDetails().getFullRecordData(table, recordSysID);
        // } else {
        //     return 'Record SysId is Not Correct or have some problem';
        // }

        var inputsPayload = {};
        // quote is a input of type: glide_record
        // inputsPayload['json_object'] = data;
        inputsPayload['fcc_kyc_case'] = {
            tableName: table,
            sysId: recordSysID,
            queryString: ''
        };

       //gs.info(	"abhi-1"+JSON.stringify(inputsPayload));
        var capabilityId = '894c863e3b3fae50f13f5fea26e45a1b';
        var request = {
            executionRequests: [{
                payload: inputsPayload,
                capabilityId: capabilityId,
                meta: {
                    skillConfigId: '614cca7e3b3fae50f13f5fea26e45aaf'
                }
            }],
            mode: 'sync'
        };
        //gs.info('@@abhi0'+request);
        try {
            var response = sn_one_extend.OneExtendUtil.execute(request) || {};
			//gs.info('@abhi2'+response);
            var skillResponse = ((response["capabilities"] || {})[capabilityId] || {})["response"];
			//gs.info("abhi3"+skillResponse+"");
            var results = JSON.parse(skillResponse);
            var plainText = results.model_output.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
            //gs.info('@@@asifa plainText = ' + plainText);

            return plainText;
        } catch (e) {
            gs.error(e);
            return 'Something went wrong while executing skill.';
        }

    },
    // extractQuoteContent: function(input) {
    //     var result = {
    //         summary: '',
    //         emailSubject: '',
    //         emailBody: ''
    //     };

    //     // Split summary and email sections
    //     var summaryMatch = input.match(/Summary:\s*([\s\S]*?)\s*Email:/);
    //     var emailMatch = input.match(/Email:\s*([\s\S]*)/);

    //     if (summaryMatch) {
    //         result.summary = summaryMatch[1].trim();
    //     }

    //     if (emailMatch) {
    //         var emailText = emailMatch[1].trim();

    //         // Extract subject
    //         var subjectMatch = emailText.match(/Subject:\s*(.+?)\s*\n/);
    //         if (subjectMatch) {
    //             result.emailSubject = subjectMatch[1].trim();
    //         }

    //         // Remove subject line from email body
    //         result.emailBody = emailText.replace(/Subject:\s*.+?\n/, '').trim();
    //     }

    //     return result;
    // },
    type: 'FinCrimeSummarize'
});
